let db;export async function openDB(){db=await new Promise((res,rej)=>{let r=indexedDB.open('home-library-album',1);r.onupgradeneeded=()=>r.result.createObjectStore('state');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});return new Promise((res,rej)=>{const r=db.transaction('state').objectStore('state').get('library');r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)})}export async function saveBooks(books){return new Promise((res,rej)=>{let t=db.transaction('state','readwrite');t.objectStore('state').put(books,'library');t.oncomplete=res;t.onerror=()=>rej(t.error);t.onabort=()=>rej(t.error)})}export function validateBackup(v){if(v?.format!=='home-library-v1'||!Array.isArray(v.books))throw Error('Невідомий формат резервної копії');for(const b of v.books){if(!b||typeof b.id!=='string'||typeof b.title!=='string'||!b.title.trim()||!b.work||!b.edition||!Array.isArray(b.work.genres)||!Array.isArray(b.quotes)||!b.quotes.every(q=>typeof q.text==='string')||!['Хочу прочитати','Читаю','Прочитано','Відкладено'].includes(b.status)||!(b.rating===null||(typeof b.rating==='number'&&b.rating>=1&&b.rating<=5&&b.rating*2%1===0))||(b.cover&&!(typeof b.cover==='string'&&/^data:image\/(png|jpeg|webp);base64,/.test(b.cover))))throw Error('Копія містить некоректні дані');}if(new Set(v.books.map(b=>b.id)).size!==v.books.length)throw Error('У копії повторюються ідентифікатори');return v.books}
